import uuid
import tempfile
from collections import namedtuple

from lxml import objectify
import xmltodict

from taf.internal.scf import SCF
from taf.internal.scf.exceptions import ElementNotFound

__all__ = ['NotificationMsg', 'Default', 'NotificationGroup',
           'extract_xml_value', 'NotificationType', 'AttachmentType']


class NotificationGroup(object):
    NOTIFICATIONS = None

    @classmethod
    def matching_notifications(cls, filter_name, msg_group, soap, attachment):
        for message in cls.NOTIFICATIONS:
            if message.matches(soap, attachment):
                yield message(filter_name, msg_group, attachment, soap)


class NotificationMsg(object):
    def __init__(self, filter_name, msg_group, attachment, soap, other=None):
        self.msg_group = msg_group
        self.filter_name = filter_name
        self.attachment = attachment
        self.id = uuid.uuid4()
        self.soap = soap
        self.other = other

    def __str__(self):
        class_repr = "[{class_type} ; id: {id} ; filter: {filter} ; group: {group}]"
        return class_repr.format(
            class_type=type(self),
            id=self.id,
            filter=self.filter_name,
            group=self.msg_group
        )

    __repr__ = __str__

    @staticmethod
    def matches(soap, attachment):
        raise NotImplementedError


class Default(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(Default, self).__init__(*args, **kwargs)

    @staticmethod
    def matches(soap, attachment):
        return True


def extract_xml_value(soap, name):
    result = soap.xpath(
        '//*[starts-with(local-name(), "{name}")]'.format(name=name))
    if len(result) == 1:
        return result[0].text
    else:
        return None


class Omes(object):
    def __init__(self, content):
        self.content = content


class Oats(object):
    def __init__(self, content):
        self.content = content


class Ofas(object):
    def __init__(self, content):
        self.alarms = None
        self.notification = {}

        alarms_dict = xmltodict.parse(content)

        if 'alarmSynchronisation' in alarms_dict:
            alarms = alarms_dict['alarmSynchronisation']
            self.alarms = self._ensure_list_type(alarms['alarmNew']) if 'alarmNew' in alarms else []
        elif 'notification' in alarms_dict:
            alarms = alarms_dict['notification']
            if 'alarmCleared' in alarms:
                self.notification['alarms_cleared'] = self._ensure_list_type(alarms['alarmCleared'])
            if 'alarmNew' in alarms:
                self.notification['alarms_new'] = self._ensure_list_type(alarms['alarmNew'])
            if 'alarmChanged' in alarms:
                self.notification['alarms_changed'] = self._ensure_list_type(alarms['alarmChanged'])

    @staticmethod
    def _ensure_list_type(alarms):
        return alarms if isinstance(alarms, list) else [alarms]


class Ocos(object):
    def __init__(self, content):
        self.managed_objects = self._get_managed_objects(content)
        self.content = content

    def _get_raml(self, content):
        with tempfile.NamedTemporaryFile() as temp:
            temp.write(content)
            temp.seek(0)

            scf = SCF(temp.name)
            return scf.raml

    def _get_managed_objects(self, content):
        return self._get_raml(content).cmData.get_all_descendant_mos()

    def get_managed_objects_for_class(self, class_name, exact_match=True):
        mos = []
        for mo in self.managed_objects:
            if exact_match:
                if mo["class"].lower().endswith(class_name.lower()):
                    mos.append(mo)
            else:
                if class_name.lower() in mo["class"].lower():
                    mos.append(mo)
        return mos

    def has_elements(self, mo, elements):
        try:
            for e in elements:
                mo.__getattr__(e)
        except (AttributeError, ElementNotFound):
            return False
        return True


ManagedObjectResult = namedtuple(
    'ManagedObjectResult',
    ['status', 'dist_name', 'operation', 'mo_class', 'errorCode', 'errorText']
)


class Feedback(object):
    def __init__(self, content):
        feedback = objectify.fromstring(content)

        self.managed_objects = []
        for mo in feedback.managedObjects.getchildren():
            attributes = mo.attrib
            error_code = getattr(mo, 'errorCode', None)
            error_text = getattr(mo, 'errorText', None)
            self.managed_objects.append(
                ManagedObjectResult(attributes['status'],
                                    attributes['distName'],
                                    attributes['operation'],
                                    attributes['class'],
                                    error_code[:] if error_code else None,
                                    error_text[:] if error_text else None
                                    )
            )

        self.n_successful = feedback.attrib['successful']
        self.n_unsuccessful = feedback.attrib['unsuccessful']
        self.status = feedback.attrib['status']
        self.message_result = feedback.message_result.text

    def get_managed_objects_for_class(self, class_name):
        mos = []
        for mo in self.managed_objects:
            if mo.mo_class.lower().endswith(class_name.lower()):
                mos.append(mo)
        return mos

    def __repr__(self):
        msg = 'Status: {}, Result: {}'.format(self.status, self.message_result)
        for index, mo in enumerate(self.managed_objects, start=1):
            msg += '\n  MO-{}: [{}]'.format(index, mo)
        return msg


class AttachmentProperties(object):
    def __init__(self, content):
        self.compression = extract_xml_value(content, "compression")
        self.content_type = extract_xml_value(content, "contentType")


class TransferNotification(object):
    def __init__(self, content):
        self.queue_id = extract_xml_value(content, "queueId")
        self.notification_type = extract_xml_value(content, "notificationType")
        self.attachment_properties = AttachmentProperties(content)


class ReportOperationStatus(object):
    def __init__(self, content):
        self.operation_id = extract_xml_value(content, "operationId")
        self.attachment_properties = AttachmentProperties(content)


class ReportOperationInterrupt(object):
    def __init__(self, content):
        self.operation_id = extract_xml_value(content, "operationId")
        self.reason = extract_xml_value(content, "reason")
        self.attachment_properties = AttachmentProperties(content)


class NotificationType(object):
    ReportOperationInterrupt = ReportOperationInterrupt
    ReportOperationStatus = ReportOperationStatus
    TransferNotification = TransferNotification

    SoapMapping = {"reportOperationStatus": ReportOperationStatus,
                   "transferNotification": TransferNotification,
                   "reportOperationInterrupt": ReportOperationInterrupt}


class AttachmentType(object):
    Ocos = Ocos
    Oats = Oats
    Omes = Omes
    Ofas = Ofas
    Feedback = Feedback

    ContentTypeMapping = {"ocos": Ocos, "ofas": Ofas, "omes": Omes,
                          "oats": Oats, "feedback": Feedback}
